import {environmentState} from './league.js';
export function voyageIcon(level){const c=level.color;const content=level.theme==='station'?`<ellipse cx="37" cy="29" rx="24" ry="12" fill="none" stroke="${c}"/><ellipse cx="37" cy="29" rx="12" ry="24" fill="none" stroke="${c}"/><circle cx="37" cy="29" r="7" fill="${c}" fill-opacity=".5"/>`:level.theme==='space'?`<circle cx="37" cy="29" r="14" fill="${c}" fill-opacity=".28"/><ellipse cx="37" cy="29" rx="30" ry="8" fill="none" stroke="${c}" transform="rotate(-25 37 29)"/>`:level.theme==='interstellar'?`<circle cx="37" cy="29" r="20" fill="none" stroke="${c}"/><path d="M37 9c31 12 12 47-9 32s12-35 18-15-20 18-9 3" fill="none" stroke="${c}" stroke-width="2"/>`:`<path d="M14 48q-8-25 3-37m8 37q15-24 2-32m13 32q-10-23 1-40m14 40q14-20 4-33" fill="none" stroke="${c}" stroke-width="3"/><circle cx="48" cy="14" r="3" fill="${c}" fill-opacity=".4"/>`;return `<svg class="world-icon" viewBox="0 0 75 58" aria-hidden="true">${content}</svg>`;}
export function createVoyageUI(){const info=document.createElement('div');info.className='voyage-map-heading';info.innerHTML='<div><span class="eyebrow">THE EXPEDITION MAP</span><strong>Home waters <span>01—04</span> <i>→</i> Beyond the horizon <span>05—08</span></strong></div><p>Eight worlds. Changing conditions. One very adaptable creature.</p>';document.getElementById('arenas').before(info);const badge=document.createElement('div');badge.id='environment-hud';badge.innerHTML='<span id="environment-symbol">↓</span><div><strong id="environment-label"></strong><small id="environment-phase"></small></div><div id="environment-cycle"></div>';document.getElementById('viewport').append(badge);}
export function updateVoyageHUD(level,phase){const badge=document.getElementById('environment-hud');if(!badge)return;badge.hidden=(!level.mechanic&&level.captainRule!=='surge');document.body.dataset.world=level.theme||'home';if((!level.mechanic&&level.captainRule!=='surge'))return;const env=environmentState(level,phase);document.getElementById('environment-symbol').textContent=env.arrow;const clash=document.body.classList.contains('clash-active'),mirrored={'→':'←','←':'→','↑':'↑','↓':'↓'}[env.arrow];document.getElementById('environment-label').textContent=clash&&mirrored?`${env.label.replace(env.arrow,'').trim()} · MINT ${env.arrow} / CORAL ${mirrored}`:env.label;document.getElementById('environment-phase').textContent=`WORLD PHASE ${phase+1} / ${level.phases} · CHANGES WITH EACH MOVE`;document.getElementById('environment-cycle').innerHTML=Array.from({length:level.phases},(_,i)=>`<i class="${i===phase?'active':''}"></i>`).join('');}
